import json,pyarrow.parquet as pq,random,numpy as np,collections
rows=pq.read_table('taco_verl/train.parquet').to_pylist();a=json.load(open('taco_verl/verified_alignment_audit.json'));ev={e['row_index']:e['evidence'][0]['permutation'] for e in a['changed']}
# Check simple globally seeded preprocessing, only as a falsifiable diagnosis.
for seed in [0,1,42,123,1234,2024,2025,2026,3407]:
 for style in ['python','numpy_old','numpy_new','row_python','row_numpy']:
  rng=random.Random(seed) if style=='python' else np.random.RandomState(seed) if style=='numpy_old' else np.random.default_rng(seed)
  match=0;n=0
  for i,r in enumerate(rows):
   g=json.loads(r['reward_model']['ground_truth']);size=len(g['inputs'])
   if not 1<size<=50:continue
   order=list(range(size))
   if style=='row_python':random.Random(seed+i).shuffle(order)
   elif style=='row_numpy':order=np.random.default_rng(seed+i).permutation(size).tolist()
   else:rng.shuffle(order)
   if i in ev:
    inv=list(np.argsort(order)); labels=g['outputs'];expect=[labels[j] for j in ev[i]]
